import {escapeHTML as e,money as m,link as l,Button as B,field as f,textarea as ta,select as sel,panel as P,table as T,status as badge} from './components.js';
const btn=(label,path)=>B({label,href:path}),action=(label,name,id='',secondary=false)=>B({label,action:name,id,secondary});
const hidden=(name,value)=>`<input type="hidden" name="${e(name)}" value="${e(value)}">`;
let formSequence=0;
const repeatedForms=new Set(['category-rename','shop-status','moderation','return-reject','return-received','refund-record','review']);
const form=(id,body,label='Lưu thay đổi')=>`<form id="${repeatedForms.has(id)?id+'-'+(++formSequence):id}" data-form="${id}" class="market-form">${body}${label?B({label,type:'submit'}):''}</form>`;
const metrics=items=>`<div class="metric-grid">${items.map(([title,value])=>P(title,`<strong>${value}</strong>`)).join('')}</div>`;
const sellerNav=[['seller','Tổng quan'],['seller/products','Sản phẩm'],['seller/orders','Đơn hàng'],['seller/inventory','Kho & biến thể'],['seller/returns','Trả hàng'],['seller/finance','Báo cáo thu COD'],['seller/shipping','Vận chuyển'],['seller/profile','Hồ sơ gian hàng']];
const adminNav=[['admin','Tổng quan'],['admin/approvals','Duyệt người bán'],['admin/shops','Quản lý gian hàng'],['admin/moderation','Kiểm duyệt sản phẩm'],['admin/categories','Ngành hàng'],['admin/coupons','Ưu đãi'],['admin/users','Người dùng'],['admin/disputes','Trả hàng & tranh chấp'],['admin/reports','Báo cáo'],['admin/audit','Nhật ký hệ thống']];
const status=p=>!p.visible?'Đã ẩn':p.moderation==='approved'?'Đã duyệt':p.moderation==='rejected'?'Bị gỡ':'Chờ duyệt';
export function renderWorkspace(s,path,{orderList,orderView,returnTable}){
  const [kind,route,id]=path.split('/'),admin=kind==='admin',shop=s.shops.find(x=>x.id===s.shopId);
  if(!s.user||s.user.role!==(admin?'admin':'seller'))return `<main id="main" class="container page"><h1>${s.user?'Không có quyền truy cập':'Vui lòng đăng nhập'}</h1><p>Khu vực này yêu cầu tài khoản ${admin?'quản trị':'người bán'} được cấp quyền.</p>${btn('Về trang mua sắm','')}${btn('Đăng nhập','login')}</main>`;
  const ps=s.products.filter(p=>p.shopId===s.shopId),os=s.orders.filter(o=>o.shopId===s.shopId);let title='',body='';
  if(!admin){switch(route){
    case 'products':title='Sản phẩm của gian hàng';body=btn('Thêm sản phẩm','seller/product-new')+T(['Sản phẩm','Giá từ','Tồn','Trạng thái',''],ps.map(p=>[e(p.name),m(p.price),p.stock,status(p)+(p.reason?'<br><small>'+e(p.reason)+'</small>':''),l('seller/product/'+p.id,'Sửa')+' · '+(p.visible?l('seller/delete/'+p.id,'Ẩn sản phẩm'):l('seller/product/'+p.id,'Mở bán lại'))]));break;
    case 'product':case 'product-new':title='Thông tin sản phẩm';body=P('Sản phẩm & phân loại',productForm(s,id));break;
    case 'delete':title='Ẩn sản phẩm';body=P(title,`<p>Sản phẩm ngừng hiển thị công khai. Lịch sử đơn hàng được giữ lại.</p>${action('Xác nhận ẩn','archive',id)}${btn('Quay lại','seller/products')}`);break;
    case 'inventory':title='Kho & biến thể';body=form('inventory',T(['Sản phẩm','Phân loại / SKU','Tồn có thể bán'],ps.flatMap(p=>p.skus.map(x=>[e(p.name),e(x.label)+' · '+e(x.code),`<input aria-label="Kho ${e(p.name)} ${e(x.label)}" type="number" min="0" max="1000000" step="1" required name="${e(x.id)}" value="${x.stock}">`]))),'Lưu tồn kho');break;
    case 'orders':title='Đơn hàng của gian hàng';body=orderList(true);break;
    case 'order':title='Chi tiết đơn hàng';body=orderView(id,true);break;
    case 'returns':title='Trả hàng / hoàn tiền';body=returnTable(s.returns.filter(x=>x.shopId===s.shopId),'seller');break;
    case 'finance':title='Báo cáo thu COD';body=financialReport(s);break;
    case 'shipping':title='Thiết lập vận chuyển';body=shop?P(title,form('shipping',f('Phí giao hàng mỗi đơn (đ)','shipping',shop.shipping,'number',true,'min="0" step="1"')+f('Địa chỉ lấy hàng','pickup',shop.pickup||'','text',true))):'<p>Chưa có gian hàng.</p>';break;
    case 'profile':title='Hồ sơ gian hàng';body=shop?P(title,form('shop-profile',f('Tên gian hàng','name',shop.name,'text',true)+ta('Giới thiệu','description',shop.description||''))):'<p>Chưa có gian hàng.</p>';break;
    default:title='Tổng quan gian hàng';body=metrics([['Đơn cần xử lý',os.filter(o=>o.status==='Chờ xác nhận').length],['Sản phẩm đang bán',ps.filter(p=>p.visible&&p.moderation==='approved').length],['Đơn đã hoàn thành',os.filter(o=>o.status==='Hoàn thành').length],['Yêu cầu trả hàng',s.returns.filter(r=>r.shopId===s.shopId&&r.status!=='Đã hoàn tiền').length]])+P(shop?.name||'Gian hàng',`<p>Trạng thái: ${e(shop?.status||'Chưa được cấp')}</p><p>Sản phẩm, đơn hàng và tồn kho được quản lý riêng theo gian hàng.</p>`)+orderList(true);
  }}else{switch(route){
    case 'approvals':title='Duyệt người bán';body=T(['Gian hàng / hồ sơ','Chủ sở hữu','Trạng thái','Xử lý'],s.applications.map(a=>[e(a.name)+`<details><summary>Thông tin hồ sơ</summary><p>${e(a.category)}<br>${e(a.legalName)}<br>${e(a.bank)}</p></details>`,e(a.owner),badge(a.status)+(a.reason?'<p>'+e(a.reason)+'</p>':''),a.status==='Chờ duyệt'?f('Lý do yêu cầu bổ sung','reason-'+a.id)+action('Phê duyệt','approve',a.id)+action('Yêu cầu bổ sung','reject',a.id):'Đã xử lý']));break;
    case 'shops':title='Quản lý gian hàng';body=T(['Gian hàng','Ngành hàng','Trạng thái','Thay đổi trạng thái'],s.shops.map(x=>[e(x.name),e(x.category),badge(x.status),['Đang hoạt động','Đã khóa'].includes(x.status)?form('shop-status',hidden('shopId',x.id)+sel('Trạng thái','status',['Đang hoạt động','Đã khóa'],x.status)+f('Lý do','reason'),'Cập nhật'):'Chưa xét duyệt']));break;
    case 'product':{const p=s.products.find(p=>p.id===id);title='Kiểm tra sản phẩm';body=p?P(p.name,`<img src="${e(p.photo||'./assets/'+p.image+'.svg')}" width="240" height="200" alt="${e(p.name)}"><p>${e(p.category)} · ${e(s.shops.find(x=>x.id===p.shopId)?.name)}</p><p>${e(p.description)}</p><p>${e(p.attributes)}</p><p>Trạng thái: ${e(status(p))}</p>${T(['Phân loại','SKU','Giá','Tồn'],p.skus.map(x=>[e(x.label),e(x.code),m(x.price),x.stock]))}${p.moderation==='approved'?form('moderation',hidden('productId',p.id)+hidden('moderation','rejected')+f('Lý do gỡ','reason','','text',true),'Gỡ khỏi sàn'):action('Phê duyệt','moderate',p.id)}${btn('Về danh sách','admin/moderation')}`):P('Không tìm thấy sản phẩm','');break;}
    case 'moderation':title='Kiểm duyệt sản phẩm';body=T(['Sản phẩm','Gian hàng','Trạng thái','Xử lý'],s.products.map(p=>[l('admin/product/'+p.id,e(p.name)),e(s.shops.find(x=>x.id===p.shopId)?.name),status(p),p.moderation==='approved'?form('moderation',hidden('productId',p.id)+hidden('moderation','rejected')+f('Lý do gỡ','reason','','text',true),'Gỡ khỏi sàn'):action('Phê duyệt','moderate',p.id)]));break;
    case 'categories':title='Ngành hàng';body=P('Thêm ngành hàng',form('category',f('Tên ngành hàng','name','','text',true),'Thêm'))+T(['Ngành hàng','Đổi tên',''],s.categories.map(c=>[e(c),form('category-rename',hidden('oldName',c)+f('Tên mới','name',c,'text',true),'Lưu'),action('Xóa ngành hàng','delete-category',c,true)]));break;
    case 'coupons':title='Quản lý ưu đãi';body=P('Tạo ưu đãi',form('create-coupon',`<div class="form-grid">${f('Mã ưu đãi','code','','text',true)}${sel('Phạm vi','shopId',[{value:'',label:'Toàn sàn'},...s.shops.filter(x=>x.status==='Đang hoạt động').map(x=>({value:x.id,label:x.name}))])}${f('Mức giảm cố định (đ)','amount','','number',true,'min="1" step="1"')}${f('Tiền hàng tối thiểu (đ)','minimum',0,'number',true,'min="0" step="1"')}${f('Tổng lượt sử dụng','maxUses',100,'number',true,'min="1" step="1"')}${f('Ngày bắt đầu','start','','date',true)}${f('Ngày kết thúc','end','','date',true)}</div>`,'Tạo ưu đãi'))+T(['Mã','Phạm vi','Giảm','Điều kiện','Hạn',''],s.coupons.map(c=>[e(c.code),e(s.shops.find(x=>x.id===c.shopId)?.name||'Toàn sàn'),m(c.amount),m(c.minimum),e(c.end),action(c.enabled?'Tắt':'Bật','toggle-coupon',c.code)]));break;
    case 'users':title='Người dùng';body=T(['Họ tên','Email','Vai trò'],s.users.map(u=>[e(u.name),e(u.email),e(u.role)]));break;
    case 'disputes':title='Trả hàng & tranh chấp';body=returnTable(s.returns,'admin');break;
    case 'reports':case 'settlements':title='Báo cáo thu COD';body=financialReport(s);break;
    case 'audit':title='Nhật ký hệ thống';body=T(['Thời gian','Tài khoản','Thao tác','Đối tượng','Chi tiết'],(s.audit||[]).map(a=>[e(a.date),e(a.userId),e(a.action),e(a.targetId),e(a.details)]));break;
    default:title='Tổng quan toàn sàn';body=metrics([['Gian hàng chờ duyệt',s.applications.filter(a=>a.status==='Chờ duyệt').length],['Sản phẩm chờ duyệt',s.products.filter(p=>p.moderation==='pending').length],['Đơn hàng',s.orders.length],['Tranh chấp đang mở',s.returns.filter(r=>r.dispute&&r.status!=='Đã hoàn tiền').length]])+financialReport(s);
  }}
  return `<div class="workspace"><header class="workspace-top">${l('',admin?'Chợ PTIT / quản trị sàn':'Chợ PTIT / kênh người bán')}<div>${admin?e(s.profile.name):`<label>Gian hàng <select id="shop-select">${s.shopIds.map(id=>`<option value="${e(id)}" ${id===s.shopId?'selected':''}>${e(s.shops.find(x=>x.id===id)?.name)}</option>`).join('')}</select></label>`} · ${l('account','Tài khoản')}</div></header><div class="workspace-row"><aside class="workspace-nav">${(admin?adminNav:sellerNav).map(([p,t])=>l(p,t,path===p?'active':'')).join('')}${l('','← Về sàn mua sắm')}${action('Đăng xuất','logout')}</aside><main id="main" tabindex="-1" class="workspace-content"><h1>${e(title)}</h1>${body}</main></div></div>`;
}
function financialReport(s){const r=s.report||{};return metrics([['Tiền hàng đã thu',m(r.merchandisePaid)],['Phí giao hàng đã thu',m(r.shippingPaid)],['Hoàn tiền đã ghi nhận',m(r.refunds)],['Tổng thu sau hoàn',m(r.netCollected)]])+P('Thống kê theo gian hàng',T(['Gian hàng','Số đơn','Tổng COD đã thu'],(r.byShop||[]).map(x=>[e(x.name),x.orders,m(x.paid)])))+'<p class="muted">Số thu COD được ghi nhận khi người mua xác nhận nhận hàng và thanh toán. Báo cáo không thay thế chứng từ chuyển tiền hoặc xác nhận của đơn vị vận chuyển.</p>';}

function productForm(s,id){const product=id=>s.products.find(x=>x.id===id);const p=product(id)||{name:'',category:s.categories[0],description:'',attributes:'',brand:'',skus:[]};if(p.shopId&&p.shopId!==s.shopId)return P('Không có quyền sửa sản phẩm này','');return form('product-edit',`<input type="hidden" name="id" value="${e(id||'')}">${sel('Ngành hàng','category',s.categories,p.category)}${f('Tên sản phẩm','name',p.name,'text',true)}${f('Thương hiệu / Xuất xứ','brand',p.brand)}${ta('Mô tả sản phẩm','description',p.description)}<img src="${e(p.photo||'./assets/'+(p.image||'product-placeholder')+'.svg')}" width="240" height="200" alt="Ảnh sản phẩm hiện tại">${f('Thuộc tính theo ngành hàng','attributes',p.attributes)}<label class="upload">Ảnh PNG/JPEG, tối đa 2 MB<input name="photo" type="file" accept="image/png,image/jpeg"></label>${p.skus.length?T(['Phân loại','Mã SKU','Giá bán (đ)','Tồn kho','Trọng lượng (g)'],p.skus.map(x=>[f('Phân loại','label-'+x.id,x.label,'text',true),f('SKU','code-'+x.id,x.code,'text',true),f('Giá','price-'+x.id,x.price,'number',true,'min="0" step="1"'),f('Kho','stock-'+x.id,x.stock,'number',true,'min="0" step="1"'),f('Trọng lượng','weight-'+x.id,x.weight,'number',true,'min="0" step="1"')])):''}<details ${!p.skus.length?'open':''}><summary>${p.skus.length?'Thêm phân loại':'Phân loại sản phẩm'}</summary><div class="form-grid">${f('Phân loại mới (ngăn cách bằng dấu phẩy)','newVariants',p.skus.length?'':'Tiêu chuẩn','text',!p.skus.length)}${f('Tiền tố mã SKU','newSku',p.skus.length?'':'SKU-'+Date.now())}${f('Giá bán phân loại mới','newPrice',0,'number',false,'min="0" step="1"')}${f('Tồn mỗi phân loại mới','newStock',0,'number',false,'min="0" step="1"')}${f('Trọng lượng (g)','newWeight',350,'number',false,'min="0" step="1"')}</div></details><p class="notice">Mỗi phân loại có mã SKU, giá và tồn riêng. Sản phẩm thêm hoặc sửa sẽ được gửi kiểm duyệt trước khi hiển thị công khai.</p>`,'Lưu & gửi duyệt');}
